 "content": "from collections import Counter


def transform(grid):
    """Reduce each aligned 3x3 cell to its non-background marker color."""
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError("grid dimensions must be divisible by 3")
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = Counter(
                grid[i][j]
                for i in range(r, r + 3)
                for j in range(c, c + 3)
                if grid[i][j] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
